import { useEffect, useState, type FormEvent } from 'react'
import {
  createExpense,
  fetchExpenses,
  ValidationError,
  type Expense,
  type FieldErrors,
} from './api'

export function ExpensesScreen() {
  const [expenses, setExpenses] = useState<Expense[] | null>(null)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [label, setLabel] = useState('')
  const [amount, setAmount] = useState('')
  const [currency, setCurrency] = useState('EUR')
  const [errors, setErrors] = useState<FieldErrors>({})
  const [formError, setFormError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    const controller = new AbortController()
    fetchExpenses(controller.signal)
      .then(setExpenses)
      .catch((e: unknown) => {
        if (controller.signal.aborted) return
        setLoadError(e instanceof Error ? e.message : 'Failed to load expenses')
      })
    return () => controller.abort()
  }, [])

  async function onSubmit(e: FormEvent) {
    e.preventDefault()
    if (submitting) return
    setSubmitting(true)
    setErrors({})
    setFormError(null)
    try {
      const created = await createExpense({
        label,
        amount: Number(amount),
        currency,
      })
      setExpenses((prev) => [...(prev ?? []), created])
      setLabel('')
      setAmount('')
    } catch (err) {
      if (err instanceof ValidationError) {
        setErrors(err.errors)
        const known = ['label', 'amount', 'currency']
        const other = Object.entries(err.errors)
          .filter(([k]) => !known.includes(k))
          .map(([, m]) => m)
        if (other.length) setFormError(other.join(' '))
      } else {
        setFormError(err instanceof Error ? err.message : 'Submission failed')
      }
    } finally {
      setSubmitting(false)
    }
  }

  function field(name: string) {
    const msg = errors[name]
    return {
      'aria-invalid': msg ? true : undefined,
      'aria-describedby': msg ? `${name}-error` : undefined,
    }
  }

  function message(name: string) {
    return errors[name] ? (
      <span id={`${name}-error`} role="alert">
        {errors[name]}
      </span>
    ) : null
  }

  return (
    <main>
      <h1>My expenses</h1>

      {loadError ? (
        <p role="alert">{loadError}</p>
      ) : expenses === null ? (
        <p>Loading…</p>
      ) : expenses.length === 0 ? (
        <p>No expenses yet.</p>
      ) : (
        <ul>
          {expenses.map((x) => (
            <li key={x.id}>
              {x.label} — {x.amount.toFixed(2)} {x.currency} ({x.status})
            </li>
          ))}
        </ul>
      )}

      <h2>New expense</h2>
      <form onSubmit={onSubmit} noValidate>
        <div>
          <label htmlFor="label">Label</label>
          <input
            id="label"
            value={label}
            onChange={(e) => setLabel(e.target.value)}
            {...field('label')}
          />
          {message('label')}
        </div>
        <div>
          <label htmlFor="amount">Amount</label>
          <input
            id="amount"
            type="number"
            step="0.01"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            {...field('amount')}
          />
          {message('amount')}
        </div>
        <div>
          <label htmlFor="currency">Currency</label>
          <input
            id="currency"
            value={currency}
            onChange={(e) => setCurrency(e.target.value)}
            {...field('currency')}
          />
          {message('currency')}
        </div>
        {formError && <p role="alert">{formError}</p>}
        <button type="submit" disabled={submitting}>
          {submitting ? 'Submitting…' : 'Submit expense'}
        </button>
      </form>
    </main>
  )
}
